import { format, resolveConfig } from "prettier";

// Generates the portable Agent Plugins package (plugin.json + mcp.json +
// assets + ZIP) used by the current OpenAI Plugins submission flow.
// Source of truth for listing copy and review cases is the Apps SDK
// submission manifest (chatgpt-app-submission.json), which is itself
// generated by scripts/generate-openai-submission.ts. Run
// `bun run submission:generate` first when tool metadata changes.
//
// Format references (2026-11-09):
// - https://developers.openai.com/plugins/build/plugins
// - https://developers.openai.com/plugins/deploy/submission

const manifestPath = "chatgpt-app-submission.json";
const packageDir = "plugin-package";
const pluginJsonPath = `${packageDir}/plugin.json`;
const mcpJsonPath = `${packageDir}/mcp.json`;
const zipPath = "dist/munch-plugin.zip";
const checkOnly = process.argv.includes("--check");

const MCP_SERVER_URL = "https://munch.business/mcp";
// Mirrors MUNCH_DEFAULT_OAUTH_SCOPES in src/auth/oauth-scopes.ts.
const OAUTH_SCOPES = ["nutrition.read", "nutrition.write", "offline_access"];

const ASSETS: Record<string, string> = {
    "assets/logo.png": "public/brand/munch-mark-512.png",
    "assets/icon.png": "public/brand/munch-mark-512.png",
    "assets/logo-dark.svg": "public/brand/munch-mark-light.svg",
    "assets/icon-dark.svg": "public/brand/munch-mark-light.svg",
};

interface LegacyTestCase {
    description: string;
    user_prompt: string;
    file_attachment_urls: string[] | null;
    tools_triggered: string | null;
    expected_output: string;
    expected_output_url: string | null;
}

interface LegacyManifest {
    app_info: {
        display_name: string;
        subtitle: string;
        description: string;
        category: string;
    };
    test_cases: LegacyTestCase[];
    negative_test_cases: LegacyTestCase[];
}

function assertLimit(label: string, value: string, max: number): void {
    if (value.length > max) {
        throw new Error(`${label} exceeds ${max} characters (${value.length})`);
    }
}

function mapPositiveCase(testCase: LegacyTestCase) {
    if (!testCase.tools_triggered) {
        throw new Error(
            `Positive test case is missing tools_triggered: ${testCase.description}`,
        );
    }
    return {
        description: testCase.description,
        prompt: testCase.user_prompt,
        tools_triggered: testCase.tools_triggered,
        expected_behavior: testCase.expected_output,
        ...(testCase.file_attachment_urls
            ? { file_attachment_urls: testCase.file_attachment_urls }
            : {}),
        ...(testCase.expected_output_url
            ? { expected_output_url: testCase.expected_output_url }
            : {}),
    };
}

function mapNegativeCase(testCase: LegacyTestCase) {
    return {
        description: testCase.description,
        prompt: testCase.user_prompt,
        expected_behavior: testCase.expected_output,
    };
}

function createPluginJson(manifest: LegacyManifest, version: string) {
    const { app_info } = manifest;
    // Starter prompts from docs/openai-submission/listing-copy.md; the
    // Plugins format accepts at most three (the old format had no cap and
    // the listing copy suggests six).
    const defaultPrompt = [
        "Log the lunch in this photo after I review the portions.",
        "Show my calorie and macro totals for the last seven days.",
        "Look up the nutrition for this barcode.",
    ];
    const capabilities = [
        "Log meals with review and confirmation",
        "Look up foods and barcodes",
        "Manage recipes and meal plans",
        "Track goals, trends, and history",
    ];

    assertLimit("displayName", app_info.display_name, 30);
    assertLimit("shortDescription", app_info.subtitle, 30);
    assertLimit("longDescription", app_info.description, 4000);
    for (const prompt of defaultPrompt) assertLimit("defaultPrompt", prompt, 128);
    if (capabilities.length > 20) throw new Error("Too many capabilities");
    for (const capability of capabilities) {
        assertLimit("capability", capability, 120);
    }
    if (manifest.test_cases.length !== 5) {
        throw new Error("Initial MCP review requires exactly five positive cases");
    }
    if (manifest.negative_test_cases.length !== 3) {
        throw new Error("Initial MCP review requires exactly three negative cases");
    }

    return {
        $schema: "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
        name: "munch",
        version,
        description:
            "Track meals, nutrition, recipes, and grocery lists privately from any MCP client.",
        author: {
            name: "Sportfolio Holdings",
            email: "support@munch.business",
            url: "https://munch.business",
        },
        homepage: "https://munch.business",
        license: "MIT",
        keywords: [
            "nutrition",
            "food",
            "meal tracking",
            "recipes",
            "grocery list",
            "meal planning",
        ],
        extensions: {
            "com.openai": {
                interface: {
                    displayName: app_info.display_name,
                    shortDescription: app_info.subtitle,
                    longDescription: app_info.description,
                    developerName: "Sportfolio Holdings",
                    // The Plugins format takes a dashboard category title;
                    // the old manifest used the Apps SDK code "FOOD".
                    category: "Food & Drink",
                    capabilities,
                    websiteURL: "https://munch.business",
                    supportURL: "https://munch.business/help",
                    privacyPolicyURL: "https://munch.business/privacy",
                    termsOfServiceURL: "https://munch.business/terms",
                    defaultPrompt,
                    // Site theme-color in public/index.html.
                    brandColor: "#176b3a",
                    // Primary fill of public/brand/munch-mark.svg.
                    brandColorDark: "#0B8F4D",
                    composerIcon: "./assets/icon.png",
                    composerIconDark: "./assets/icon-dark.svg",
                    logo: "./assets/logo.png",
                    logoDark: "./assets/logo-dark.svg",
                },
                review: {
                    test_cases: {
                        positive: manifest.test_cases.map(mapPositiveCase),
                        negative:
                            manifest.negative_test_cases.map(mapNegativeCase),
                    },
                    // demo_recording_url is required before MCP review but
                    // the walkthrough video does not exist yet; it must be
                    // added here (and the package regenerated) once recorded.
                    commerce: false,
                    commerce_description:
                        "Munch does not sell products or process payments in ChatGPT. Munch Premium is optional, is purchased and managed only on the Munch website, and is never advertised or sold through the plugin.",
                },
                publication: {
                    release_notes:
                        "Initial release of Munch for ChatGPT: source-aware food and barcode lookup (USDA FoodData Central, Open Food Facts), meal logging with review and explicit confirmation, saved foods and recipes including URL import with a review step, meal plans, grocery lists, goals, and trends across 95 tools. Sign-in uses OAuth 2.1 and identity comes from the authorized account. Munch is a consumer wellness product and does not provide medical advice, diagnosis, or treatment.",
                    // countries and translations are intentionally omitted:
                    // country targeting is a submission-time decision, and
                    // no translated listing copy exists yet.
                },
            },
        },
    };
}

function createMcpJson() {
    return {
        $schema: "https://agent-plugins.org/schemas/1.0.0/mcp.schema.json",
        mcpServers: {
            munch: {
                type: "streamable-http",
                url: MCP_SERVER_URL,
                extensions: {
                    "com.openai": {
                        auth: {
                            type: "oauth",
                            // Munch supports Dynamic Client Registration;
                            // endpoints come from OAuth discovery, so no
                            // registrationUrl or endpoint overrides are set.
                            client: { mode: "dcr" },
                            baseScopes: OAUTH_SCOPES,
                        },
                    },
                },
            },
        },
    };
}

async function requireExactFile(path: string, expected: string): Promise<void> {
    const file = Bun.file(path);
    if (!(await file.exists())) {
        throw new Error(`${path} is missing; run bun run submission:plugin:generate`);
    }
    const actual = await file.text();
    if (actual !== expected) {
        throw new Error(`${path} is stale; run bun run submission:plugin:generate`);
    }
}

async function requireAssetCopy(
    packageRelativePath: string,
    sourcePath: string,
): Promise<void> {
    const target = Bun.file(`${packageDir}/${packageRelativePath}`);
    if (!(await target.exists())) {
        throw new Error(
            `${packageDir}/${packageRelativePath} is missing; run bun run submission:plugin:generate`,
        );
    }
    const [actual, expected] = await Promise.all([
        target.arrayBuffer(),
        Bun.file(sourcePath).arrayBuffer(),
    ]);
    if (Buffer.from(actual).equals(Buffer.from(expected)) === false) {
        throw new Error(
            `${packageDir}/${packageRelativePath} is stale; run bun run submission:plugin:generate`,
        );
    }
}

const manifest = (await Bun.file(manifestPath).json()) as LegacyManifest;
const packageJson = (await Bun.file("package.json").json()) as {
    version: string;
};

const pluginPrettierConfig = (await resolveConfig(pluginJsonPath)) ?? {};
const mcpPrettierConfig = (await resolveConfig(mcpJsonPath)) ?? {};
const pluginText = await format(JSON.stringify(createPluginJson(manifest, packageJson.version)), {
    ...pluginPrettierConfig,
    filepath: pluginJsonPath,
});
const mcpText = await format(JSON.stringify(createMcpJson()), {
    ...mcpPrettierConfig,
    filepath: mcpJsonPath,
});

if (checkOnly) {
    await requireExactFile(pluginJsonPath, pluginText);
    await requireExactFile(mcpJsonPath, mcpText);
    for (const [packageRelativePath, sourcePath] of Object.entries(ASSETS)) {
        await requireAssetCopy(packageRelativePath, sourcePath);
    }
    console.log(`Plugin package is current (version ${packageJson.version}).`);
} else {
    await Bun.write(pluginJsonPath, pluginText);
    await Bun.write(mcpJsonPath, mcpText);
    for (const [packageRelativePath, sourcePath] of Object.entries(ASSETS)) {
        await Bun.write(
            `${packageDir}/${packageRelativePath}`,
            Bun.file(sourcePath),
        );
    }
    await Bun.$`mkdir -p dist`;
    await Bun.$`rm -f ${zipPath}`;
    // Zip the folder contents so plugin.json sits at the archive root.
    await Bun.$`zip -r -X ${`../${zipPath}`} .`.cwd(packageDir);
    console.log(
        `Generated ${pluginJsonPath}, ${mcpJsonPath}, ${Object.keys(ASSETS).length} assets, and ${zipPath} (version ${packageJson.version}).`,
    );
}
